n=16
x=[[8]*n for _ in range(n)]
x[0][0]=6
for r in range(n): x[r][6]=1
for r in range(4):
    for c in range(12,16): x[r][c]=1
for r in range(7,10):
    for c in range(9,11): x[r][c]=1
for r in range(13,16):
    for c in range(10,12): x[r][c]=1
# perimeter background 7
y=[row[:] for row in x]
for r in range(n):
    for c in range(n):
        if r in (0,n-1) or c in (0,n-1):
            if y[r][c]==8: y[r][c]=7
# find 1 components via 8-neighbor, note component touches boundary; color adjacent 8s
seen=set()
for r in range(n):
  for c in range(n):
    if x[r][c]==1 and (r,c) not in seen:
      stack=[(r,c)]; seen.add((r,c)); comp=[]
      while stack:
        a,b=stack.pop(); comp.append((a,b))
        for da in (-1,0,1):
          for db in (-1,0,1):
            q=(a+da,b+db)
            if 0<=q[0]<n and 0<=q[1]<n and x[q[0]][q[1]]==1 and q not in seen:
              seen.add(q);stack.append(q)
      if any(a in (0,n-1) or b in (0,n-1) for a,b in comp):
        for a,b in comp:
          for da in (-1,0,1):
            for db in (-1,0,1):
              aa,bb=a+da,b+db
              if 0<=aa<n and 0<=bb<n and y[aa][bb]==8: y[aa][bb]=7
print('\n'.join(' '.join(map(str,row)) for row in y))

